examples.code:
DROP TABLE IF EXISTS staff;
CREATE TABLE staff (staff_id INTEGER PRIMARY KEY, full_name TEXT, salary INTEGER);
INSERT INTO staff VALUES (1,'Asha',42000),(2,'Bilal',65000),(3,'Chitra',90000);
SELECT full_name, CASE WHEN salary<50000 THEN 'Entry' WHEN salary<80000 THEN 'Mid' ELSE 'Senior' END AS salary_band FROM staff ORDER BY staff_id;

DROP TABLE IF EXISTS tickets;
CREATE TABLE tickets (ticket_id INTEGER PRIMARY KEY, status_code INTEGER);
INSERT INTO tickets VALUES (1,1),(2,2),(3,3),(4,9);
SELECT ticket_id, CASE status_code WHEN 1 THEN 'Open' WHEN 2 THEN 'In progress' WHEN 3 THEN 'Closed' ELSE 'Unknown' END AS status_label FROM tickets ORDER BY ticket_id;

DROP TABLE IF EXISTS tasks;
CREATE TABLE tasks (task_id INTEGER PRIMARY KEY, task_name TEXT, priority TEXT);
INSERT INTO tasks VALUES (1,'Backup','Low'),(2,'Fix outage','High'),(3,'Update guide','Medium');
SELECT task_name,priority FROM tasks ORDER BY CASE priority WHEN 'High' THEN 1 WHEN 'Medium' THEN 2 ELSE 3 END, task_name;

DROP TABLE IF EXISTS payments;
CREATE TABLE payments (payment_id INTEGER PRIMARY KEY, amount INTEGER);
INSERT INTO payments VALUES (1,1200),(2,400),(3,900),(4,250);
SELECT SUM(CASE WHEN amount>=800 THEN 1 ELSE 0 END) AS large_payments, COUNT(*) AS all_payments FROM payments;

DROP TABLE IF EXISTS contacts;
CREATE TABLE contacts (contact_id INTEGER PRIMARY KEY, phone TEXT);
INSERT INTO contacts VALUES (1,'98765'),(2,NULL);
SELECT contact_id, CASE WHEN phone IS NULL THEN 'Missing phone' ELSE 'Available' END AS phone_status FROM contacts ORDER BY contact_id;

